// 死锁：加锁顺序相反
void transfer(Account a, Account b) {
    synchronized (a) { synchronized (b) { /* ... */ } }
}
// 修复：按 id 排序固定加锁顺序
void safeTransfer(Account a, Account b) {
    Account first = a.id < b.id ? a : b, second = first == a ? b : a;
    synchronized (first) { synchronized (second) { /* ... */ } }
}
