@RabbitListener(queues = "order.q", ackMode = "MANUAL")
public void onMsg(Message m, Channel ch) throws IOException {
    long tag = m.getMessageProperties().getDeliveryTag();
    try { handleIdempotent(m); ch.basicAck(tag, false); }
    catch (Exception e) { ch.basicNack(tag, false, false); } // 不重入队，进死信
}

